@dataclass(frozen=True)
class RegressionCheck:
    """Публичное имя сценария отдельно от исполняемой функции."""

    name: str
    run: Callable[[str], tuple[bool, str]]

    def __iter__(self):
        # Совместимость с существующими потребителями пар (имя, функция).
        yield self.name
        yield self.run


